    debug_assert!(mid >= 0 && (mid as usize) < v.len());

    if v[mid as usize] <= elem {
        // mid is ≤ elem, so the last ≤ elem is in [mid+1 .. f] or at mid.
        // Measure decreases: new interval length is f - (mid+1) + 1 = f - mid.
        binary_search_recursive(v, elem, mid + 1, f)
    } else {
        // mid is > elem, so the last ≤ elem is in [c .. mid-1].
        // Measure decreases: new interval length is (mid-1) - c + 1 = mid - c.
        binary_search_recursive(v, elem, c, mid - 1)
    }
